import {filterRecords, sortRecords, generateChoices, buildCSV, parseCSV, validateImport} from './domain.js';

const $ = (q, root=document) => root.querySelector(q);
const e = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = value => { try { const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:'#'; } catch {return '#';} };
const unique = a => [...new Set(a.filter(v=>v!==null&&v!==undefined&&v!==''))];
const num = n => n===null||n===undefined||n===''?'—':new Intl.NumberFormat('en-IN').format(n);
const money = n => n===null||n===undefined?'Not reported':`₹${num(n)}`;
const shortMoney = n => n===null||n===undefined?'—':n>=100000?`₹${(n/100000).toFixed(n%100000===0?0:1)}L`:money(n);
const ID = () => crypto.randomUUID?.() || `id-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const EXAMS=['NEET PG'];
const STORE='zyjock.pg.workspace.v2';
let stored={};try{stored=JSON.parse(localStorage.getItem(STORE)||'{}')||{}}catch{}
let state={exam:'NEET PG',mode:stored.mode||'verified',lists:stored.lists||[{id:'first-list',name:'My first choice list',items:[]}],reminders:stored.reminders||[],checklist:stored.checklist||{},imports:stored.imports||{records:[],institutes:[]},readNotices:stored.readNotices||[],activeList:stored.activeList||'first-list',filters:{},sort:'name',view:'cards',visible:36,profile:stored.profile||{},compare:[],mobileOpen:false};
if(!Array.isArray(state.lists)||!state.lists.length||state.lists.some(l=>!l||!Array.isArray(l.items)||typeof l.name!=='string'))state.lists=[{id:'first-list',name:'My first choice list',items:[]}];
if(!Array.isArray(state.reminders))state.reminders=[];
if(!state.imports||!Array.isArray(state.imports.records)||!Array.isArray(state.imports.institutes))state.imports={records:[],institutes:[]};
if(!Array.isArray(state.readNotices))state.readNotices=[];
if(!state.checklist||typeof state.checklist!=='object')state.checklist={};
let data, modalReturnFocus=null, instituteIndex=new Map(), recordIndex=new Map(), fullRecords=[], fullInstitutes=[];
const rankOf=r=>r.recordKind==='seat-matrix'?(r.historicalClosingRank??null):(r.closingRank??null);
const rankContext=r=>r.recordKind==='seat-matrix'?(r.historicalYear?`${r.historicalYear} · ${r.historicalRound}`:'No matched historical cutoff'):`${r.year} · ${r.round}`;
function refreshCatalog(){fullInstitutes=[...data.institutes,...state.imports.institutes];fullRecords=[...data.records,...state.imports.records];instituteIndex=new Map(fullInstitutes.map(i=>[i.id,i]));recordIndex=new Map(fullRecords.map(r=>[r.id,r]));}
const paths={home:'Overview',colleges:'College & hospital explorer',cutoffs:'Historical cutoffs',fees:'Fees, stipends & bonds',seats:'2026 seat matrix',choices:'My choice lists',rounds:'Round tracker',updates:'Updates & calendar',rank:'Rank comparison',specialties:'Specialty explorer',profile:'My PG plan',guides:'Guidance library',data:'Data & sources'};
const glyphs={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',college:'m3 8 9-5 9 5-9 5zM5 10v7m5-4v4m4-4v4m5-7v7M3 21h18M3 18h18',chart:'M4 20V4m0 16h17M8 15l4-5 4 2 5-7',wallet:'M3 6h17v14H3zM3 6V4h14v2m-1 5h6v5h-6z',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',list:'M9 6h12M9 12h12M9 18h12M3 5l1 1 2-2m-3 7 1 1 2-2m-3 7 1 1 2-2',repeat:'M4 7h14l-3-3m3 3-3 3M20 17H6l3 3m-3-3 3-3',bell:'M6 9a6 6 0 0 1 12 0c0 7 3 7 3 9H3c0-2 3-2 3-9m3 12h6',calculator:'M5 2h14v20H5zM8 6h8M8 10h1m6 0h1m-8 4h1m6 0h1m-8 4h1m6 0h1',book:'M12 5C9 3 5 3 2 4v15c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1zm0 0v15',database:'M3 5c0-4 18-4 18 0s-18 4-18 0zm0 0v14c0 4 18 4 18 0V5M3 12c0 4 18 4 18 0',arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',check:'m5 12 4 4L19 6',plus:'M12 5v14M5 12h14',search:'M21 21l-5-5m2-6a7 7 0 1 1-14 0 7 7 0 0 1 14 0',close:'m6 6 12 12M6 18 18 6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',upload:'M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7',pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0zm-7-3v5',heart:'M20 4c-4-3-8 3-8 3S8 1 4 4c-5 4 0 10 8 17 8-7 13-13 8-17z',menu:'M3 6h18M3 12h18M3 18h18',info:'M12 16v-5m0-4h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',up:'m6 15 6-6 6 6',calendar:'M3 5h18v16H3zM7 2v6m10-6v6M3 10h18',clock:'M12 7v5l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',scale:'M12 3v18M5 21h14M3 7h18M5 7 2 15h6L5 7zm14 0-3 8h6l-3-8z',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6zM7 12l3 3 7-7'};
const icon=(name,cls='')=>`<svg class="${cls}" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${glyphs[name]||glyphs.book}"/></svg>`;
const btn=(label,action,cls='secondary',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const badge=s=>`<span class="badge ${s==='verified'?'success':s==='demo'?'demo':'warning'}">${s==='verified'?'Official source':s==='demo'?'Demo data':'Imported · unverified'}</span>`;
const external=(url,label)=>safeUrl(url)==='#'?'<span class="text-muted">Source not supplied</span>':`<a class="source-link" href="${e(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${e(label)} ${icon('external')}</a>`;
const institutes=()=>fullInstitutes;
const records=()=>fullRecords;
const inst=id=>instituteIndex.get(id)||{name:'Unnamed institution',state:'Unknown',city:'',type:'Unknown'};
const rec=id=>recordIndex.get(id);
const selectedList=()=>state.lists.find(l=>l.id===state.activeList)||state.lists[0];
const route=()=>Object.hasOwn(paths,location.hash.slice(1))?location.hash.slice(1):'home';
const baseRecords=()=>records().filter(r=>r.exam==='NEET PG'&&(state.mode==='all'||r.dataStatus===state.mode)&&(['cutoffs','rounds'].includes(route())?r.recordKind!=='seat-matrix':r.recordKind!=='cutoff')&&(r.seats!==0||(route()==='seats'&&state.filters.includeZero==='yes')));
const filtered=()=>sortRecords(filterRecords(baseRecords(),{...state.filters,...(route()==='seats'?{rank:''}:{}),exam:state.exam,dataMode:state.mode},institutes()),state.sort,institutes());
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));return true}catch{toast('Browser storage is full or unavailable. Download a backup before leaving.','warning');return false}}
function toast(message,type='success'){const node=document.createElement('div');node.className=`toast ${type}`;node.innerHTML=icon(type==='success'?'check':'info')+`<span>${e(message)}</span>`;$('#toast-root').append(node);setTimeout(()=>node.remove(),4800)}
function navigate(path){state.mobileOpen=false;if(location.hash===`#${path}`)render();else location.hash=path;window.scrollTo(0,0)}
function sourceNote(){const historical=['cutoffs','rounds'].includes(route());return `<div class="data-note">${icon('shield')}<span>${state.mode==='imported'?'Your imported PG records are unverified and saved in this browser.':`${historical?'Historical MCC PG allotments':'Published MCC 2026 PG seat matrices'} · checked ${e(data.updatedAt)}. ${historical?'Opening and closing ranks are derived by allotted seat category.':'Past cutoffs, where matched, keep their own year and round.'}`} <a href="#data">Coverage & sources</a></span></div>`}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><div class="breadcrumb">Your counselling workspace <span>/</span> ${e(state.exam)}</div><h1 class="page-title">${title}</h1><p class="page-subtitle">${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`}
function empty(title='No records match these filters',text='Try another category, state or data source.',action='reset-filters'){return `<div class="empty-state"><div class="empty-icon">${icon('search')}</div><h3>${e(title)}</h3><p>${e(text)}</p>${action?btn(action==='switch-demo'?'Import PG data':'Reset filters',action):''}</div>`}
function option(value,label,selected){return `<option value="${e(value)}" ${String(value)===String(selected)?'selected':''}>${e(label??value)}</option>`}
function selectField(name,label,values,selected='',first='All'){return `<label class="filter-field"><span>${e(label)}</span><select name="${name}">${option('',first,selected)}${values.map(v=>option(v,v,selected)).join('')}</select></label>`}
function filterPanel({rank=true,fees=false,round=true}={}){const rs=baseRecords();return `<form id="filter-form" class="panel filters"><div class="toolbar"><label class="filter-field search-field"><span>Find a college or course</span><div class="search-input">${icon('search')}<input name="search" placeholder="Search name, city, course…" value="${e(state.filters.search||'')}"></div></label>${selectField('state','State',unique(rs.map(r=>inst(r.instituteId).state)).sort(),state.filters.state)}${selectField('specialty','Specialty',unique(rs.map(r=>r.specialty)).sort(),state.filters.specialty)}${selectField('program','Programme',unique(rs.map(r=>r.program)).sort(),state.filters.program)}${selectField('category','Seat category',unique(rs.map(r=>r.category)).sort(),state.filters.category)}${selectField('quota','Quota',unique(rs.map(r=>r.quota)).sort(),state.filters.quota)}</div><div class="toolbar">${rank?`<label class="filter-field"><span>Your NEET PG AIR</span><input name="rank" type="number" min="1" step="1" placeholder="Your AIR (optional)" value="${e(state.filters.rank||'')}"></label>`:''}${selectField('year','Source year',unique(rs.map(r=>r.year)).sort((a,b)=>b-a),state.filters.year)}${round?selectField('round','Round',unique(rs.map(r=>r.round)).sort(),state.filters.round):''}${fees?`<label class="filter-field"><span>Maximum annual tuition (₹)</span><input name="maxFee" type="number" min="0" placeholder="No limit" value="${e(state.filters.maxFee||'')}"></label>`:''}<label class="filter-field"><span>Sort by</span><select name="sort">${[['name','College name'],['closingRank','Closing rank'],['annualFee','Tuition: low to high'],['seats','Seats: high to low']].map(([v,l])=>option(v,l,state.sort)).join('')}</select></label>${route()==='seats'?`<label class="checkbox-row"><input name="includeZero" type="checkbox" value="yes" ${state.filters.includeZero==='yes'?'checked':''}><span>Include zero-seat pools</span></label>`:''}<div class="filter-buttons"><button class="btn primary" type="submit">Apply filters</button>${btn('Reset','reset-filters','subtle')}</div></div></form>`}
function initials(name){return name.split(/\s+/).filter(w=>!/^(of|the|and|in)$/i.test(w)).slice(0,2).map(w=>w[0]).join('').toUpperCase()}
function collegeCell(r){const i=inst(r.instituteId);return `<div class="college-cell"><span class="college-avatar">${e(initials(i.name))}</span><div><button class="college-name" data-action="detail" data-id="${e(r.id)}">${e(i.name)}</button><div class="college-meta">${e(i.city||i.state)} · ${e(r.course)}</div></div></div>`}
function saveButton(r){if(r.seats===0)return '<span class="small text-muted">No seats</span>';const saved=selectedList()?.items.includes(r.id);return `<button class="icon-btn ${saved?'is-saved':''}" aria-label="${saved?'Already saved':'Save '+e(inst(r.instituteId).name)}" title="${saved?'Already in active list':'Add to active choice list'}" data-action="save-record" data-id="${e(r.id)}">${icon(saved?'check':'plus')}</button>`}
function collegeCard(r){const i=inst(r.instituteId);return `<article class="college-card"><div class="college-card-top"><span class="college-avatar large">${e(initials(i.name))}</span>${saveButton(r)}</div><div class="college-card-body"><div class="college-meta">${e(i.type||'Institute')} <span>·</span> ${e(i.state)}</div><h3><button data-action="detail" data-id="${e(r.id)}">${e(i.name)}</button></h3><p class="small text-muted">${e(r.course)} · ${e(r.quota)} · ${e(r.category)}</p><p class="small text-muted">Published seats: ${e(r.year)} ${e(r.round)} · Cutoff: ${e(rankContext(r))}</p><div class="college-metrics"><div><span>Historical closing AIR</span><strong>${num(rankOf(r))}</strong></div><div><span>Annual tuition</span><strong>${shortMoney(r.annualFee)}</strong></div><div><span>Seats</span><strong>${num(r.seats)}</strong></div></div></div><div class="college-card-footer">${badge(r.dataStatus)}<button class="btn subtle" data-action="compare" data-id="${e(r.id)}">${icon('scale')} Compare</button></div></article>`}
function recordTable(rows,kind='cutoffs'){const columns=kind==='fees'?['Institute & specialty','Annual tuition','Monthly stipend','Bond years','Bond penalty','Evidence','']:kind==='seats'?['Institute & specialty','Quota / category','Year · round','Seats','Previous comparison','Evidence','']:['Institute & specialty','Quota / category','Cutoff year · round','Opening AIR','Closing AIR','Evidence',''];return `<div class="table-wrap"><table class="data-table"><thead><tr>${columns.map(c=>`<th>${e(c)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td>${collegeCell(r)}</td>${kind==='fees'?`<td>${money(r.annualFee)}</td><td>${money(r.monthlyStipend)}</td><td>${num(r.bondYears)}</td><td>${money(r.bondPenalty)}</td>`:kind==='seats'?`<td>${e(r.quota)}<br><span class="text-muted">${e(r.category)}</span></td><td>${e(r.year)} · ${e(r.round)}</td><td class="numeric">${num(r.seats)}</td><td>${num(r.previousSeats)}</td>`:`<td>${e(r.quota)}<br><span class="text-muted">${e(r.category)}</span></td><td>${e(rankContext(r))}</td><td class="numeric">${num(r.recordKind==='seat-matrix'?r.historicalOpeningRank:r.openingRank)}</td><td class="numeric">${num(rankOf(r))}</td>`}<td>${badge(r.dataStatus)}</td><td>${saveButton(r)}</td></tr>`).join('')}</tbody></table></div>`}

function heroArt(){return `<svg viewBox="0 0 400 270" role="img" aria-label="An open path towards medical education"><circle cx="229" cy="127" r="98" fill="#e7edcb"/><circle cx="229" cy="127" r="74" fill="none" stroke="#a3b096" stroke-dasharray="3 7"/><path d="M92 216c20-62 61-26 88-80s76-33 126-89" fill="none" stroke="#749684" stroke-width="3" stroke-dasharray="6 7"/><g transform="rotate(-8 204 155)"><rect x="112" y="116" width="181" height="112" rx="14" fill="#254a41"/><rect x="106" y="105" width="181" height="112" rx="14" fill="#fff" stroke="#d4dccd"/><path d="M196 124v72M124 132c27-7 48-3 65 7v51c-18-9-41-13-65-6zm145 0c-27-7-48-3-65 7v51c18-9 41-13 65-6z" fill="#eff3df"/><path d="M135 145h33m-33 10h37m-37 10h26M219 146h31m-31 11h26" stroke="#8fa28e" stroke-width="3" stroke-linecap="round"/></g><g transform="rotate(10 285 78)"><rect x="239" y="39" width="99" height="69" rx="13" fill="#fff" stroke="#d4dccd"/><circle cx="263" cy="64" r="12" fill="#d6f266"/><path d="m258 64 4 4 6-8" fill="none" stroke="#254a41" stroke-width="2"/><path d="M283 61h35m-35 8h23M254 88h61" stroke="#abb8aa" stroke-width="3" stroke-linecap="round"/></g><circle cx="102" cy="89" r="30" fill="#d6f266"/><path d="M102 72v34M85 89h34" stroke="#254a41" stroke-width="7"/><path d="m328 178 7 13 14 3-10 10 1 15-12-7-13 6 3-14-10-11 15-2z" fill="#e8ba7d"/><circle cx="77" cy="181" r="6" fill="#6c9780"/></svg>`}
function pgMetrics(){const rows=data.records.filter(r=>r.recordKind==='seat-matrix'&&r.dataStatus==='verified');return{rows,seats:rows.reduce((s,r)=>s+(r.seats||0),0),colleges:data.coverage?.currentInstitutes??unique(rows.map(r=>r.instituteId)).length,specialties:unique(rows.map(r=>r.specialty)).length,cutoffs:data.records.filter(r=>r.recordKind==='cutoff').length}}
function profilePage(){const rs=data.records.filter(r=>r.recordKind==='seat-matrix'),p=state.profile;return heading('Make this your PG plan.','Set a starting point for your research. Your preferences stay on this device.',btn('Explore with my plan','apply-profile','primary'))+`<div class="grid cols-2"><section class="panel"><div class="panel-header"><h2>Your preferences</h2><span class="badge success">LOCAL & PRIVATE</span></div><form id="profile-form" class="panel-body form-grid"><label class="field"><span>NEET PG All India rank</span><input name="rank" type="number" min="1" value="${e(p.rank||'')}" placeholder="Optional"></label>${selectField('category','Seat category to explore',unique(rs.map(r=>r.category)).sort(),p.category)}${selectField('specialty','Preferred specialty',unique(rs.map(r=>r.specialty)).sort(),p.specialty)}${selectField('state','Preferred state',unique(rs.map(r=>inst(r.instituteId).state)).sort(),p.state)}<label class="field"><span>Maximum annual tuition (₹)</span><input name="maxFee" type="number" min="0" value="${e(p.maxFee||'')}" placeholder="Optional"></label><button class="btn primary">Save my plan ${icon('check')}</button><p class="small text-muted">A tuition limit excludes unknown fees. No options are labelled eligible or guaranteed. Verify quota and category requirements yourself.</p></form></section><section class="panel"><div class="panel-header"><h2>Your PG counselling checklist</h2></div><div class="panel-body">${checklistView()}<p class="small text-muted">Use the current MCC and state bulletins for the full document list and eligibility conditions.</p><a class="source-link" href="#guides">Read the PG guides ${icon('arrow')}</a></div></section></div>`}
function specialties(){const rs=baseRecords().filter(r=>r.seats>0),groups=new Map();for(const r of rs){const key=r.specialty||r.course;if(!groups.has(key))groups.set(key,{name:key,rows:[],seats:0});const g=groups.get(key);g.rows.push(r);g.seats+=r.seats}const q=(state.branchSearch||'').toLowerCase();const rows=[...groups.values()].filter(g=>(g.name+' '+({'Radio-diagnosis':'radiology radiodiagnosis','Otorhinolaryngology (ENT)':'ear nose throat','Obstetrics & Gynaecology':'obg obgyn gynecology'}[g.name]||'')).toLowerCase().includes(q)).sort((a,b)=>b.seats-a.seats);return heading('Find your specialty.','See where each branch is offered, then compare the actual programme, institution and seat pool.')+sourceNote()+`<form id="specialty-search" class="panel filters"><label class="filter-field search-field"><span>Search specialties</span><input name="search" placeholder="Try radiology, medicine or surgery…" value="${e(state.branchSearch||'')}"></label><button class="btn primary">Find specialty</button></form><p class="small text-muted">${rows.length} specialties in this dataset. Seat totals include all published quotas and categories; they do not establish your eligibility.</p><div class="grid cols-3">${rows.map(g=>`<article class="specialty-card"><span class="stat-icon">${icon('book')}</span><h2>${e(g.name)}</h2><div class="specialty-numbers"><div><strong>${num(g.seats)}</strong><span>published seats</span></div><div><strong>${unique(g.rows.map(r=>r.instituteId)).length}</strong><span>institutions</span></div></div><p class="small text-muted">${e(unique(g.rows.map(r=>r.program)).join(' · '))}</p>${btn('Explore this specialty '+icon('arrow'),'specialty','secondary',`data-id="${e(g.name)}"`)}</article>`).join('')}</div>`}
function timelineView(){const today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'});const all=(data.timeline||[]).slice().sort((a,b)=>(a.endDate||a.date).localeCompare(b.endDate||b.date));const events=route()==='home'?all.filter(t=>t.authority==='MCC'&&(t.endDate||t.date)>=today).slice(0,6):all;if(!events.length)return '';return `<section class="panel section-gap"><div class="panel-header"><div><span class="badge neutral">2026 COUNSELLING SCHEDULES</span><h2>Keep the next deadline in sight.</h2></div><a class="source-link" href="#updates">All updates ${icon('arrow')}</a></div><div class="timeline-grid">${events.map(t=>`<article class="timeline-event"><span class="timeline-date">${e(t.date)}${t.endDate&&t.endDate!==t.date?' → '+e(t.endDate):''}</span><h3>${e(t.title)}</h3><p class="small text-muted">${e(t.authority||'MCC')}${t.scope?' · '+e(t.scope):''}</p><p>${e(t.time||'')}${t.time?' · ':''}${e(t.description||'')}</p>${external(t.sourceUrl,'Official schedule')} ${btn(t.endDate&&t.endDate!==t.date?'Remind me on the closing date':'Add reminder','schedule-reminder','subtle',`data-id="${e(t.id)}"`)}</article>`).join('')}</div><p class="small text-muted panel-body">Snapshot checked ${e(data.updatedAt)}. Authorities may revise dates. Confirm the linked schedule before acting; reminders do not automatically update.</p></section>`}
function home(){const m=pgMetrics(),saved=state.lists.reduce((n,l)=>n+l.items.length,0);return heading('Your next specialty starts here.','A focused, free workspace for NEET PG counselling.',`<span class="chip">${icon('check')} Every PG tool is free</span>`)+`<section class="hero"><div class="hero-copy"><span class="hero-kicker">NEET PG · YOUR NEXT CHAPTER</span><h2 class="hero-title">A clearer choice.<br>A future that fits you.</h2><p class="hero-text">Explore MD, MS and DNB options. Put your rank, specialty and budget in perspective before you build your list.</p><div class="hero-actions"><a class="btn primary" href="#colleges">Explore PG options ${icon('arrow')}</a><a class="btn secondary" href="#profile">Make my PG plan</a></div><div class="hero-stats"><span>${icon('shield')} Official sources, dated clearly</span><span>${icon('heart')} No subscriptions</span></div></div><div class="hero-art">${heroArt()}</div></section><section class="grid cols-4 section-gap"><div class="stat-card"><span class="stat-icon">${icon('grid')}</span><span class="metric-label">2026 published seats</span><strong class="metric-value">${num(m.seats)}</strong><a href="#seats" class="small">Explore the MCC matrices ${icon('arrow')}</a></div><div class="stat-card"><span class="stat-icon">${icon('college')}</span><span class="metric-label">Colleges & hospitals</span><strong class="metric-value">${num(m.colleges)}</strong><span class="small text-muted">In the published MCC snapshot</span></div><div class="stat-card"><span class="stat-icon">${icon('chart')}</span><span class="metric-label">Historical cutoff records</span><strong class="metric-value">${num(m.cutoffs)}</strong><a href="#cutoffs" class="small">Inspect each year and round ${icon('arrow')}</a></div><div class="stat-card"><span class="stat-icon">${icon('list')}</span><span class="metric-label">Your saved choices</span><strong class="metric-value">${saved}</strong><a href="#choices" class="small">Unlimited lists & exports ${icon('arrow')}</a></div></section><section class="grid cols-3 section-gap">${[['specialties','book','Start with a specialty','Explore branches, programmes and the institutions offering them.'],['rank','chart','Start with your rank','Compare your AIR with previous allotted seat pools.'],['fees','wallet','Plan the real cost','Compare reported fees and bonds, or build your own budget.']].map(([path,ic,title,desc])=>`<a class="resource-card" href="#${path}"><span class="stat-icon">${icon(ic)}</span><h3>${title}</h3><p>${desc}</p><span class="source-link">Open tool ${icon('arrow')}</span></a>`).join('')}</section>${timelineView()}<section class="grid cols-2 section-gap"><div class="panel"><div class="panel-header"><h2>Your counselling checklist</h2><span class="small text-muted">Saved on this device</span></div><div class="panel-body">${checklistView()}</div></div><div class="panel"><div class="panel-header"><h2>Know the process before you choose.</h2></div><div class="panel-body"><p>Understand the current MCC process, documents and reporting steps. Keep state counselling requirements separate from the All India process.</p><a class="btn secondary" href="#guides">Read the PG guidance ${icon('arrow')}</a><p class="small text-muted">Use the source register to inspect scope, gaps and how historical observations were matched.</p></div></div></section>${sourceNote()}`}

const checks=[['rank','Keep your NEET PG scorecard and AIR ready'],['eligibility','Read 2026 MCC and relevant state bulletins'],['documents','Prepare MBBS, internship and registration documents'],['compare','Compare colleges, costs and bonds'],['choices','Prepare a ranked preference list']];
function checklistView(){return checks.map(([id,label])=>`<label class="checkbox-row"><input type="checkbox" data-check="${id}" ${state.checklist[id]?'checked':''}><span>${label}</span>${state.checklist[id]?icon('check'):''}</label>`).join('')}
function colleges(){const rows=filtered(),display=rows.slice(0,state.visible);return heading('A college that fits your plans.','Explore institutions and course options. Save the ones you want to come back to.',btn(`${icon('download')} Export results`,'export-results'))+sourceNote()+filterPanel()+`<div class="toolbar results-bar"><p><strong>${num(rows.length)}</strong> matching records <span class="text-muted">· ${unique(rows.map(r=>r.instituteId)).length} colleges</span></p><div class="tabs"><button class="tab ${state.view==='cards'?'active':''}" data-action="cards">${icon('grid')} Cards</button><button class="tab ${state.view==='table'?'active':''}" data-action="table">${icon('list')} Table</button></div></div>`+(rows.length?(state.view==='cards'?`<div class="card-grid">${display.map(collegeCard).join('')}</div>`:recordTable(display)):`${empty('No colleges in this view',baseRecords().length?'Try broader filters.':'No PG records are available in this source mode. Switch to official data or import your own PG dataset.',baseRecords().length?'reset-filters':'switch-demo')}`)+(rows.length>state.visible?`<div class="toolbar section-gap">${btn('Show more records','show-more')}<span class="small text-muted">Showing ${state.visible} of ${num(rows.length)}. Export includes every match.</span></div>`:'')}
function financialSourcesView(){const d=data.dnbAnnualFeeReference;return (d?`<section class="panel section-gap"><div class="panel-header"><h2>DNB annual fee policy reference</h2><span class="badge neutral">${e(d.year)} · NBEMS</span></div><div class="panel-body"><p>Listed heads: tuition ${money(d.tuition)}, library ${money(d.library)}, appraisal ${money(d.appraisal)}, accommodation ${money(d.accommodation)}. Total: <strong>${money(d.totalOfListedHeads)}</strong>.</p><p>${e(d.notes)}</p>${external(d.sourceUrl,'Read the NBEMS policy')}</div></section>`:'')+ `<section class="panel section-gap"><div class="panel-header"><h2>Reported financial examples</h2><span class="badge neutral">SOURCE-SPECIFIC</span></div><div class="panel-body grid cols-2">${(data.financials||[]).map(f=>`<article class="resource-card"><h3>${e(f.instituteName||f.title||'Official fee reference')}</h3><p>${e(f.course||f.program||'PG programme')} · ${e(f.year)}</p><p>Reported tuition: <strong>${money(f.annualFee)}</strong><br>Monthly stipend: <strong>${money(f.monthlyStipend)}</strong><br>Service bond: <strong>${f.bondYears==null?'Not reported':num(f.bondYears)+' years'}</strong></p><p class="small text-muted">${e(f.feeScope||'')} ${e(f.notes||'')}</p>${external(f.sourceUrl,f.sourceLabel||'Institution source')}</article>`).join('')}</div></section>`}
function analysisPage(kind){const rs=kind==='fees'?filtered().filter(r=>r.annualFee!=null||r.monthlyStipend!=null||r.bondYears!=null||r.bondPenalty!=null):filtered();const cfg={cutoffs:['The past, in perspective.','Compare historical opening and closing ranks. Every row keeps its source year, round and seat category.'],fees:['Look beyond the tuition fee.','Bring tuition, stipend and bond obligations into the same conversation. Only records with a reported financial figure appear in this table. Other institution details remain available in the explorer.'],seats:['See where the seats are.','Inspect the official 2026 MCC seat matrices by institution, programme, quota and category. Published inventory may be revised.']}[kind];return heading(cfg[0],cfg[1],btn(`${icon('download')} Export records`,'export-results'))+sourceNote()+(kind==='fees'?financialSourcesView():'')+filterPanel({rank:kind==='cutoffs',fees:kind==='fees'})+`<div class="panel"><div class="panel-header"><h2>${num(rs.length)} ${kind==='fees'?'cost':kind==='seats'?'published seat pools':'cutoff'} records</h2><span class="small text-muted">“—” means not reported</span></div>${rs.length?recordTable(rs.slice(0,state.visible),kind):empty()}</div>${rs.length>state.visible?`<div class="toolbar section-gap">${btn('Show more records','show-more')}<span class="small text-muted">Showing ${state.visible} of ${num(rs.length)}. Export includes every match.</span></div>`:''}${kind==='fees'?`<div class="panel section-gap"><div class="panel-header"><h2>Plan the cost of a course</h2><p class="small text-muted">Your own assumptions, calculated locally.</p></div><form id="cost-form" class="panel-body form-grid"><label class="field"><span>Annual tuition (₹)</span><input type="number" name="tuition" min="0" required></label><label class="field"><span>Years of study</span><input type="number" name="years" min="0.5" max="15" step="0.5" value="3" required></label><label class="field"><span>Monthly living cost (₹)</span><input type="number" name="living" min="0" value="10000" required></label><label class="field"><span>Monthly stipend (₹)</span><input type="number" name="stipend" min="0" value="0" required></label><button class="btn primary">Calculate budget</button><div id="cost-result" aria-live="polite"></div></form></div>`:''}`}

function choices(){const list=selectedList();const rows=(list?.items||[]).map(rec).filter(Boolean);return heading('Your choices. In your order.','Build as many lists as you need. Everything is saved in this browser.',btn(`${icon('plus')} New list`,'new-list','primary'))+`<div class="free-banner">${icon('shield')}<span>Unlimited lists, comparisons and exports. No payment or account required.</span><button class="btn subtle" data-action="backup">Download a backup ${icon('download')}</button></div><div class="two-column section-gap"><div class="panel"><div class="panel-header"><div class="field"><label for="active-list">Active choice list</label><select id="active-list" data-select="list">${state.lists.map(l=>option(l.id,`${l.name} (${l.items.length})`,list?.id)).join('')}</select></div><div class="table-actions">${btn('Rename','rename-list','subtle')}${btn(icon('trash'),'delete-list','icon-btn','aria-label="Delete active list"')}</div></div><div class="panel-body">${rows.length?`<div class="choice-list">${rows.map((r,index)=>`<div class="list-item"><span class="list-number">${index+1}</span><div class="list-content">${collegeCell(r)}<p class="small text-muted">${e(r.quota)} · ${e(r.category)} · ${e(r.year)} ${r.recordKind==='cutoff'?'historical cutoff':'published seat matrix'} ${badge(r.dataStatus)}</p></div><div class="list-actions"><button class="icon-btn" data-action="move-up" data-id="${e(r.id)}" ${index===0?'disabled':''} aria-label="Move choice ${index+1} up">${icon('up')}</button><button class="icon-btn" data-action="move-down" data-id="${e(r.id)}" ${index===rows.length-1?'disabled':''} aria-label="Move choice ${index+1} down">${icon('down')}</button><button class="icon-btn" data-action="remove-choice" data-id="${e(r.id)}" aria-label="Remove choice ${index+1}">${icon('close')}</button></div></div>`).join('')}</div>`:empty('Your next chapter starts with a shortlist.','Save a college from the explorer, or use the preference builder to get started.',null)}<div class="toolbar section-gap">${btn(`${icon('download')} Export CSV`,'export-list','primary',rows.length?'':'disabled')}${btn('Print / save PDF','print-list','secondary',rows.length?'':'disabled')}<a href="#colleges" class="btn subtle">Find more colleges ${icon('arrow')}</a></div><p class="small text-muted">This is a planning list. It does not submit choices to a counselling authority.</p></div></div><aside class="panel sticky-side"><div class="panel-header"><div><span class="badge success">FREE PREFERENCE BUILDER</span><h2>A starting point, your way.</h2></div></div><form id="builder-form" class="panel-body"><p class="text-muted small">Build from the current ${e(state.mode)} ${e(state.exam)} dataset, then make the order your own.</p>${selectField('state','Preferred state',unique(baseRecords().map(r=>inst(r.instituteId).state)).sort())}${selectField('specialty','Specialty',unique(baseRecords().map(r=>r.specialty)).sort())}${selectField('program','Programme',unique(baseRecords().map(r=>r.program)).sort())}${selectField('quota','Quota',unique(baseRecords().map(r=>r.quota)).sort())}${selectField('category','Seat category',unique(baseRecords().map(r=>r.category)).sort(),'','Choose a seat category').replace('<select name="category">','<select name="category" required>')}<label class="field"><span>Rank (optional)</span><input name="rank" type="number" min="1" placeholder="Compare historical cutoffs"></label><label class="field"><span>Maximum reported annual tuition (₹)</span><input name="maxFee" type="number" min="0" placeholder="Optional; unknown fees excluded if set"></label><label class="field"><span>Prioritize</span><select name="priority"><option value="name">College name</option><option value="closingRank">Historical closing rank</option><option value="annualFee">Lower reported tuition</option><option value="seats">More published seats</option></select></label><label class="field"><span>Number of choices</span><select name="limit"><option>10</option><option>20</option><option>50</option></select></label><button class="btn primary" type="submit">Create a new draft ${icon('spark')}</button><p class="small text-muted">Uses the current seat snapshot and your selected seat category. Review each programme and its eligibility rules, then reorder the draft yourself. This is not an official choice submission.</p></form></aside></div>`}
function rounds(){let rs=filtered();const groups=new Map();for(const r of rs){const key=[r.instituteId,r.courseCode||r.course,r.quota,r.category,r.year].join('|');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r)}const all=Array.from(groups.values());return heading('Follow the rounds.','Compare the same course, quota and category across published rounds. Each observation describes an allotted seat pool; candidate identities are excluded.')+sourceNote()+filterPanel({round:false})+`<div class="panel"><div class="panel-header"><h2>Round-by-round history</h2><span class="small text-muted">${all.length} comparable seat pools</span></div>${all.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Institute & specialty</th><th>Quota / category</th><th>Source year</th><th>Published rounds</th><th>Closing rank history</th></tr></thead><tbody>${all.slice(0,state.visible).map(gr=>{gr.sort((a,b)=>String(a.round).localeCompare(String(b.round),undefined,{numeric:true}));return `<tr><td>${collegeCell(gr[0])}</td><td>${e(gr[0].quota)}<br>${e(gr[0].category)}</td><td>${e(gr[0].year)}</td><td>${gr.length}</td><td><div class="round-history">${gr.map(r=>`<span class="chip">${e(r.round)} <strong>${num(r.closingRank)}</strong></span>`).join('')}</div></td></tr>`}).join('')}</tbody></table></div>`:empty()}</div>${all.length>state.visible?`<div class="toolbar section-gap">${btn('Show more records','show-more')}<span class="small text-muted">Showing ${state.visible} of ${all.length} seat pools.</span></div>`:''}<p class="data-note">A single available round is shown as one observation. Missing rounds are not treated as unchanged data. Seat additions appear only where a comparable previous seat count is supplied.</p><div class="grid cols-3 section-gap">${rs.filter(r=>r.previousSeats!==null&&r.seats!==null).slice(0,6).map(r=>`<article class="stat-card"><span class="metric-label">${e(inst(r.instituteId).name)}</span><strong class="metric-value">${r.seats-r.previousSeats>=0?'+':''}${r.seats-r.previousSeats}</strong><p class="small">${e(r.course)} · ${e(r.category)}<br>${r.previousSeats} → ${r.seats} published seats</p>${badge(r.dataStatus)}</article>`).join('')}</div>`}

function updates(){const notices=data.notices.filter(n=>!n.exam||n.exam===state.exam||n.exam==='All');return heading('Keep the next step in sight.','Official source links and your own reminders, in one place.',btn(`${icon('plus')} Add reminder`,'new-reminder','primary'))+timelineView()+`<div class="grid cols-2"><section class="panel"><div class="panel-header"><h2>Official updates & source desks</h2><span class="badge neutral">SOURCE LINKS</span></div><div class="panel-body"><p class="small text-muted">A curated source directory, not a live notification feed. Open the authority’s page for current notices and dates.</p>${notices.length?notices.map(n=>`<article class="notice-item"><span class="notice-dot ${state.readNotices.includes(n.id)?'read':''}"></span><div><span class="small text-muted">${e(n.authority||n.exam||'Official source')}${n.date?' · '+e(n.date):''}</span><h3>${e(n.title)}</h3><p>${e(n.description||'Check the official source for the latest publication.')}</p>${external(n.url,'Open official source')} ${btn(state.readNotices.includes(n.id)?'Read':'Mark read','read-notice','subtle',`data-id="${e(n.id)}"`)}</div></article>`).join(''):empty('No source notices for this exam','Find the official authority in the guidance library.',null)}</div></section><section class="panel"><div class="panel-header"><h2>Your reminders</h2>${btn(`${icon('download')} Calendar export`,'export-calendar','subtle',state.reminders.length?'':'disabled')}</div><div class="panel-body">${state.reminders.length?state.reminders.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(r=>`<div class="list-item"><span class="stat-icon">${icon('calendar')}</span><div class="list-content"><strong>${e(r.title)}</strong><p class="small text-muted">${e(r.date)} · Your personal reminder</p></div><button class="icon-btn" data-action="delete-reminder" data-id="${e(r.id)}" aria-label="Remove ${e(r.title)}">${icon('trash')}</button></div>`).join(''):empty('A calmer calendar starts here.','Add a reminder and export it to your calendar. Zyjock does not send push notifications.',null)}<div class="section-gap">${btn('Add a personal reminder','new-reminder')}</div></div></section></div><div class="panel section-gap"><div class="panel-header"><h2>Ready when registration opens</h2></div><div class="panel-body">${checklistView()}</div></div>`}
function rankPage(){return heading('Your PG rank, with context.','Compare your All India rank with historical allotments for the exact specialty, quota and seat category.')+`<div class="grid cols-2"><section class="panel"><div class="panel-header"><h2>Find historical options</h2><span class="badge success">FREE</span></div><form id="quick-rank" class="panel-body"><label class="field"><span>Your NEET PG All India rank</span><input name="rank" type="number" min="1" required placeholder="e.g. 12,000" value="${e(state.profile.rank||'')}"></label>${selectField('category','Seat category',unique(baseRecords().map(r=>r.category)).sort(),state.profile.category)}<button class="btn primary">Explore historical PG cutoffs ${icon('arrow')}</button><p class="small text-muted">Shows historical observations with closing AIR at or beyond your rank, including institutions without a reliable match to the current matrix. This does not determine eligibility or predict allotment.</p></form></section><section class="panel"><div class="panel-header"><h2>Read the comparison correctly</h2></div><div class="panel-body"><p>A cutoff belongs to a specific institution, course, quota, allotted seat category, year and round. Category rank and All India rank are different measures.</p><p>The college explorer shows the latest available historical observation beside the separately dated 2026 seat snapshot. The historical explorer lets you inspect each round.</p><p>No unsupported marks-to-rank estimate is shown. Use the AIR printed on your NEET PG scorecard.</p><a class="btn secondary" href="#cutoffs">Inspect historical rounds ${icon('arrow')}</a></div></section></div>${sourceNote()}`}

function guides(){const guides=data.guides||[];const resources=data.resources.filter(r=>!r.exam||r.exam==='All'||r.exam===state.exam);return heading('A little guidance. A lot more clarity.','Understand the process, ask better questions, and go straight to the source.')+`<div class="panel section-gap"><div class="panel-header"><div><span class="badge success">ZYJOCK GUIDE</span><h2>What would you like to understand?</h2></div>${icon('book')}</div><form id="guide-form" class="panel-body"><div class="search-input">${icon('search')}<input name="question" placeholder="Try choice filling, documents, fees or eligibility…" aria-label="Search guidance" required><button class="btn primary">Find guidance ${icon('arrow')}</button></div><p class="small text-muted">Searches the source-linked guidance library. This is not a live AI or a human counselling service.</p><div id="guide-results" aria-live="polite"></div></form></div><div class="grid cols-3">${guides.map(g=>`<article class="guide-card"><span class="stat-icon">${icon('book')}</span><h3>${e(g.title)}</h3><p>${e(String(g.body).slice(0,160))}${String(g.body).length>160?'…':''}</p>${btn('Read guide','guide-detail','subtle',`data-id="${e(g.id)}"`)}</article>`).join('')}</div><div class="section-gap"><div class="panel-header"><h2>Go straight to the source</h2><span class="small text-muted">Official authorities and reference material</span></div><div class="grid cols-3">${resources.map(r=>`<article class="resource-card"><span class="badge neutral">${e(r.type||'Official resource')}</span><h3>${e(r.title)}</h3><p>${e(r.description||'Read current information from the official publisher.')}</p>${external(r.url,'Open resource')}</article>`).join('')}</div></div>`}
function dataPage(){const c=data.coverage||{},official=data.records.filter(r=>r.dataStatus==='verified');return heading('Every number has a source.','NEET PG coverage, source dates and your own records.',btn(`${icon('download')} Workspace backup`,'backup'))+`<div class="grid cols-3"><div class="stat-card"><span class="metric-label">2026 published seats</span><strong class="metric-value">${num(c.publishedSeats)}</strong><p>${num(c.currentInstitutes)} institutions · MCC published snapshot</p></div><div class="stat-card"><span class="metric-label">Historical cutoff observations</span><strong class="metric-value">${num(c.historicalRecords)}</strong><p>${e(c.historicalScope||'Source-specific allotment aggregates')}</p></div><div class="stat-card"><span class="metric-label">Your imported PG records</span><strong class="metric-value">${num(state.imports.records.length)}</strong><p>Unverified · stored on this device</p></div></div><div class="panel section-gap"><div class="panel-header"><h2>Coverage and limits</h2><span class="badge neutral">Checked ${e(data.updatedAt)}</span></div><div class="panel-body"><p>${e(c.summary||'Official PG sources are being assembled.')}</p><ul>${(c.limitations||[]).map(x=>`<li>${e(x)}</li>`).join('')}</ul><p>Allotment counts are not seat inventory. Published seats are not live vacancies. Unavailable financial fields remain unknown.</p><p>Zyjock is independent of Zynerd, MCC, NBEMS and counselling authorities. All tools are free. This release is focused entirely on NEET PG.</p></div></div><div class="grid cols-2 section-gap"><section class="panel"><div class="panel-header"><h2>Bring your own PG records</h2></div><div class="panel-body"><p>Import CSV or JSON records with exam set to NEET PG. Imported data stays unverified and never replaces the official snapshot.</p><div class="toolbar">${btn(`${icon('upload')} Import dataset`,'import-data','primary')}${btn('CSV template','download-template')}</div><input id="dataset-file" type="file" accept=".csv,.json" hidden><details class="section-gap"><summary>Supported fields</summary><p class="small">instituteId or instituteName, state, city, exam (NEET PG), course, specialty, program, counselling, quota, category, year, round, openingRank, closingRank, seats, annualFee, monthlyStipend, bondYears, bondPenalty, sourceUrl, sourceLabel. Leave unknown numbers blank. Maximum 5 MB.</p></details>${state.imports.records.length?btn('Remove imported data','clear-imports','danger'):''}</div></section><section class="panel"><div class="panel-header"><h2>Your workspace stays with you</h2></div><div class="panel-body"><p>Your rank, profile, lists, reminders and imports are saved in this browser. Download a backup to move them to another device.</p><div class="toolbar">${btn('Export backup','backup','primary')}${btn('Restore backup','restore-backup')}</div><input id="backup-file" type="file" accept=".json" hidden><p class="small text-muted">Official links open on the publisher’s website. Zyjock does not send your profile or rank to a counselling server. Human counselling and live AI are not included.</p></div></section></div><section class="panel section-gap"><div class="panel-header"><h2>Source register</h2></div><div class="panel-body source-register">${(data.sources||[]).map(x=>`<article><h3>${e(x.title||x.label||'Official publication')}</h3><p>${e(x.description||x.scope||'')}</p>${external(x.url,'Open official source')}</article>`).join('')}</div></section>`}

function render(){if(!data)return;refreshCatalog();const path=route();const available=baseRecords();for(const key of ['year','round','course','quota','category','specialty','program'])if(state.filters[key]&&!available.some(r=>String(r[key])===String(state.filters[key])))delete state.filters[key];document.title=`${paths[path]} · Zyjock`;const nav=[['home','home'],['profile','heart'],['specialties','book'],['colleges','college'],['cutoffs','chart'],['fees','wallet'],['seats','grid'],['choices','list'],['rounds','repeat'],['updates','bell'],['rank','calculator'],['guides','book'],['data','database']];$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar ${state.mobileOpen?'open':''}"><a href="#home" class="brand" aria-label="Zyjock home"><span class="brand-mark">z</span><span class="brand-name">zyjock<span>.</span></span></a><div class="nav-label">YOUR COUNSELLING COMPANION</div><nav class="nav-group" aria-label="Main navigation">${nav.map(([id,ic],index)=>`${index===7?'<div class="nav-label">YOUR WORKSPACE</div>':''}${index===11?'<div class="nav-label">A LITTLE HELP</div>':''}<a href="#${id}" class="nav-item ${path===id?'active':''}" ${path===id?'aria-current="page"':''}>${icon(ic,'nav-icon')}<span>${paths[id]}</span>${id==='choices'?`<span class="nav-badge">${state.lists.reduce((n,l)=>n+l.items.length,0)}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="free-card"><span class="stat-icon">${icon('spark')}</span><strong>Good guidance.<br>Zero price tags.</strong><p>Every tool is free. Your future comes first.</p><a href="#data">Made for your next chapter ${icon('arrow')}</a></div><span class="small text-muted">Independent. Open to everyone.</span></div></aside>${state.mobileOpen?'<button class="sidebar-overlay" data-action="toggle-menu" aria-label="Close navigation"></button>':''}<div class="main-shell"><header class="topbar"><div class="topbar-left"><button class="icon-btn mobile-menu" data-action="toggle-menu" aria-label="Open navigation">${icon('menu')}</button><span class="exam-select pg-exam">${icon('college')} <strong>NEET PG</strong><span class="badge neutral">2026</span></span><span class="topbar-separator"></span><span class="small text-muted desktop-only">Your postgraduate counselling workspace.</span></div><div class="topbar-right"><label class="data-select"><span class="sr-only">Data source mode</span><select id="global-mode" aria-label="Data source mode">${[['verified','Official data'],['imported','My imported data'],['all','Official + imported']].map(([v,l])=>option(v,l,state.mode)).join('')}</select></label><a class="icon-btn" href="#updates" aria-label="Updates and reminders">${icon('bell')}</a><span class="avatar" title="Your workspace is local to this browser">Y</span></div></header><main id="main" class="main-content" tabindex="-1">${({home, colleges,cutoffs:()=>analysisPage('cutoffs'),fees:()=>analysisPage('fees'),seats:()=>analysisPage('seats'),choices,rounds,updates,rank:rankPage,specialties,profile:profilePage,guides,data:dataPage}[path])()}<footer class="footer"><span><strong>zyjock.</strong> Your future, without a paywall.</span><a href="#data">Data & privacy</a><span>Independent NEET PG counselling tools</span></footer></main></div></div>${state.compare.length?`<div class="compare-bar"><strong>${state.compare.length} / 3 selected</strong><span class="small">Compare costs, ranks and seats</span>${btn('Compare now','show-compare','primary',state.compare.length<2?'disabled':'')}${btn(icon('close'),'clear-compare','icon-btn','aria-label="Clear comparison"')}</div>`:''}`}

function openModal(title,body,footer=''){modalReturnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${e(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('#modal-root input, #modal-root button, #modal-root select')?.focus(),0)}
function closeModal(){ $('#modal-root').innerHTML='';document.body.style.overflow='';modalReturnFocus?.focus?.() }
function detail(id){const r=rec(id);if(!r)return;const i=inst(r.instituteId),history=(r.historyIds||[]).map(rec).filter(Boolean),current=r.recordKind==='seat-matrix';openModal(i.name,`<div class="toolbar">${badge(r.dataStatus)}<span class="chip">${e(r.program||'PG programme')}</span><span class="text-muted">${e(i.state||'State not supplied')}</span></div><h3>${e(r.course)}</h3>${i.address?`<p class="small text-muted">${e(i.address)}</p>`:''}<p>${e(r.quota)} · ${e(r.category)}</p><div class="grid cols-3"><div class="stat-card"><span class="metric-label">Historical closing AIR</span><strong class="metric-value">${num(rankOf(r))}</strong><span class="small">${e(rankContext(r))}</span></div><div class="stat-card"><span class="metric-label">${current?'2026 published seats':'Allotments in this observation'}</span><strong class="metric-value">${num(current?r.seats:r.allotmentCount)}</strong></div><div class="stat-card"><span class="metric-label">Reported annual tuition</span><strong class="metric-value">${shortMoney(r.annualFee)}</strong><span class="small">${r.financialYear?e(r.financialYear)+' source':'Source not available'}</span></div></div>${current?`<p class="match-note">${r.historicalSourceUrl?`Institution matched by ${r.historicalMatchMethod==='unique_exact_name_state'?'unique exact name and the same state':'exact complete source address'}. Course code, quota and allotted category also match. Each observation retains its original date.`:'No reliable historical match is bundled for this exact 2026 seat pool. A missing match does not mean a new seat or easy admission.'}</p>`:''}${history.length?`<section class="section-gap"><h3>Historical allotment observations</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Year · round</th><th>Opening AIR</th><th>Closing AIR</th><th>Allotted</th><th>Source</th></tr></thead><tbody>${history.map(h=>`<tr><td>${h.year} · ${e(h.round)}</td><td>${num(h.openingRank)}</td><td>${num(h.closingRank)}</td><td>${num(h.allotmentCount)}</td><td>${external(h.sourceUrl,'MCC result')}</td></tr>`).join('')}</tbody></table></div></section>`:''}<section class="section-gap"><h3>Costs and obligations</h3><p>Annual tuition: <strong>${money(r.annualFee)}</strong><br>Monthly stipend: <strong>${money(r.monthlyStipend)}</strong><br>Service bond: <strong>${r.bondYears==null?'Not reported':num(r.bondYears)+' years'}</strong><br>Bond penalty: <strong>${money(r.bondPenalty)}</strong></p>${r.financialSourceUrl?`<p>${external(r.financialSourceUrl,r.financialSourceLabel||'Financial source')}</p><p class="small text-muted">${e(r.financialNotes||'Confirm the current institution prospectus before payment.')}</p>`:'<p class="small text-muted">Financial details are not available for this seat pool. The budget calculator accepts your own verified figures.</p>'}</section><section class="section-gap"><h3>Source context</h3><p>${e(r.year)} · ${e(r.round)} · ${e(r.sourceLabel||'Official publication')}</p><p>${external(r.sourceUrl,current?'Published seat matrix':'Final allotment result')}</p>${r.historicalSourceUrl?`<p>${external(r.historicalSourceUrl,'Matched historical result')}</p>`:''}${r.notes?`<p class="small text-muted">${e(r.notes)}</p>`:''}${i.officialUrl?external(i.officialUrl,'Institution website'):''}<p class="data-note">Published inventory can be revised. Historical ranks do not establish current eligibility or predict an allotment. Check the current MCC and institution notices.</p></section>`,btn(`${icon('plus')} Save to active choice list`,'save-record','primary',`data-id="${e(r.id)}" ${r.seats===0?'disabled':''}`))}
function exportRows(rows,name){const expanded=rows.map((r,index)=>({...r,preference:index+1,instituteName:inst(r.instituteId).name,state:inst(r.instituteId).state,city:inst(r.instituteId).city}));download(buildCSV(expanded,[...(name.includes('choice-list')?['preference']:[]),'instituteName','state','city','exam','course','counselling','quota','category','year','round','openingRank','closingRank','historicalOpeningRank','historicalClosingRank','historicalYear','historicalRound','historicalMatchMethod','seats','annualFee','monthlyStipend','bondYears','bondPenalty','financialYear','financialNotes','dataStatus','sourceUrl','historicalSourceUrl','financialSourceUrl']),name,'text/csv;charset=utf-8')}
function download(content,name,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),10000);toast('Your download is ready.')}
function addChoice(id){const list=selectedList();if(!list||!rec(id)||rec(id).seats===0)return;if(list.items.includes(id)){toast('Already in your active choice list.');return}list.items.push(id);if(save())toast(`Added to ${list.name}.`);render()}
function listNameModal(rename=false){const l=selectedList();openModal(rename?'Rename your list':'Create a choice list',`<form id="list-form"><input type="hidden" name="rename" value="${rename?'yes':'no'}"><label class="field"><span>List name</span><input name="name" maxlength="80" value="${rename?e(l.name):''}" placeholder="e.g. My All India preference list" required></label><button class="btn primary" type="submit">${rename?'Save name':'Create list'}</button></form>`)}
function confirmDialog(title,text,action){openModal(title,`<p>${e(text)}</p>`,btn('Cancel','close-modal')+btn('Confirm',action,'danger'))}
function compareModal(){const rows=state.compare.map(rec).filter(Boolean);const metrics=[['Programme',r=>r.program],['Specialty',r=>r.specialty||r.course],['Quota',r=>r.quota],['Seat category',r=>r.category],['Seat source year',r=>r.recordKind==='seat-matrix'?r.year:'No seat inventory'],['Published seats',r=>num(r.seats)],['Historical closing AIR',r=>num(rankOf(r))],['Cutoff year · round',rankContext],['Annual tuition',r=>money(r.annualFee)],['Monthly stipend',r=>money(r.monthlyStipend)],['Bond years',r=>r.bondYears==null?'Not reported':num(r.bondYears)],['Bond penalty',r=>money(r.bondPenalty)],['Financial source year',r=>r.financialYear||'Not reported']];openModal('Your PG options, side by side',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Compare</th>${rows.map(r=>`<th>${e(inst(r.instituteId).name)}</th>`).join('')}</tr></thead><tbody>${metrics.map(([label,get])=>`<tr><th>${e(label)}</th>${rows.map(r=>`<td>${e(get(r)??'Not reported')}</td>`).join('')}</tr>`).join('')}<tr><th>Official publication</th>${rows.map(r=>`<td>${external(r.sourceUrl,'Source')}</td>`).join('')}</tr></tbody></table></div><p class="data-note">Compare equivalent programmes and seat pools. Historical closing AIR is not a score for institutional quality.</p>`)}
function icsEscape(s){return String(s).replace(/\\/g,'\\\\').replace(/;/g,'\\;').replace(/,/g,'\\,').replace(/\r?\n/g,'\\n')}
function exportCalendar(){const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const text=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Zyjock//Personal reminders//EN',...state.reminders.flatMap(r=>['BEGIN:VEVENT',`UID:${r.id}@zyjock.local`,`DTSTAMP:${stamp}`,`DTSTART;VALUE=DATE:${r.date.replace(/-/g,'')}`,`SUMMARY:${icsEscape(r.title)}`,'DESCRIPTION:Personal planning reminder from Zyjock. Verify official deadlines.','END:VEVENT']),'END:VCALENDAR'].join('\r\n');download(text,'zyjock-reminders.ics','text/calendar;charset=utf-8')}

document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target)return;const a=target.dataset.action,id=target.dataset.id;event.preventDefault();switch(a){case'schedule-reminder':{const t=(data.timeline||[]).find(x=>x.id===id);if(t){state.reminders.push({id:ID(),title:`${t.title}${t.time?' · '+t.time:''} (verify ${t.authority||'official'} schedule)`,date:t.endDate||t.date});save();toast('Schedule reminder added to your personal calendar.')}break}case'apply-profile':state.filters={rank:state.profile.rank||'',category:state.profile.category||'',state:state.profile.state||'',specialty:state.profile.specialty||'',maxFee:state.profile.maxFee||''};navigate('colleges');break;case'specialty':state.filters={specialty:id};navigate('colleges');break;case'show-more':state.visible+=36;render();break;case'toggle-menu':state.mobileOpen=!state.mobileOpen;render();break;case'close-modal':closeModal();break;case'detail':detail(id);break;case'save-record':addChoice(id);break;case'reset-filters':state.filters={};state.visible=36;render();break;case'switch-demo':navigate('data');break;case'cards':state.view='cards';render();break;case'table':state.view='table';render();break;case'compare':if(state.compare.includes(id)){state.compare=state.compare.filter(x=>x!==id)}else if(state.compare.length<3){state.compare.push(id)}else{toast('Compare up to three records at a time.','warning')}render();break;case'show-compare':compareModal();break;case'clear-compare':state.compare=[];render();break;case'new-list':listNameModal();break;case'rename-list':listNameModal(true);break;case'delete-list':confirmDialog('Delete this choice list?',`Remove “${selectedList().name}” from this browser?`,'confirm-delete-list');break;case'confirm-delete-list':state.lists=state.lists.filter(l=>l.id!==selectedList().id);if(!state.lists.length)state.lists=[{id:ID(),name:'My first choice list',items:[]}];state.activeList=state.lists[0].id;save();closeModal();render();break;case'move-up':case'move-down':{const l=selectedList(),index=l.items.indexOf(id),next=index+(a==='move-up'?-1:1);if(index>=0&&next>=0&&next<l.items.length){[l.items[index],l.items[next]]=[l.items[next],l.items[index]];save();render()}break}case'remove-choice':selectedList().items=selectedList().items.filter(x=>x!==id);save();render();break;case'export-list':exportRows(selectedList().items.map(rec).filter(Boolean),'zyjock-choice-list.csv');break;case'export-results':exportRows(filtered().filter(r=>route()!=='fees'||[r.annualFee,r.monthlyStipend,r.bondYears,r.bondPenalty].some(v=>v!=null)),'zyjock-records.csv');break;case'print-list':window.print();break;case'new-reminder':openModal('Add a personal reminder',`<form id="reminder-form"><label class="field"><span>What do you want to remember?</span><input name="title" maxlength="120" required placeholder="e.g. Check the official seat matrix"></label><label class="field"><span>Date</span><input type="date" name="date" required></label><button class="btn primary">Save reminder</button><p class="small text-muted">Saved locally. Export to your calendar for notifications.</p></form>`);break;case'delete-reminder':state.reminders=state.reminders.filter(x=>x.id!==id);save();render();break;case'export-calendar':exportCalendar();break;case'read-notice':if(!state.readNotices.includes(id))state.readNotices.push(id);save();render();break;case'guide-detail':{const g=data.guides.find(g=>g.id===id);if(g)openModal(g.title,`<div class="guide-body">${String(g.body).split('\n').map(p=>`<p>${e(p)}</p>`).join('')}</div><p>${external(g.sourceUrl,'Read the official source')}</p><p class="small text-muted">General process information. Check the current authority bulletin for NEET PG and the relevant counselling authority.</p>`);break}case'backup':download(JSON.stringify({format:'zyjock-workspace',version:1,exportedAt:new Date().toISOString(),lists:state.lists,reminders:state.reminders,checklist:state.checklist,profile:state.profile,exam:'NEET PG',imports:state.imports},null,2),'zyjock-workspace.json');break;case'import-data':$('#dataset-file').click();break;case'restore-backup':$('#backup-file').click();break;case'clear-imports':confirmDialog('Remove imported records?','Imported records and their saved list entries will be removed from this browser. Download a backup first if you need them.','confirm-clear-imports');break;case'confirm-clear-imports':{const ids=new Set(state.imports.records.map(r=>r.id));state.lists.forEach(l=>l.items=l.items.filter(id=>!ids.has(id)));state.imports={records:[],institutes:[]};state.compare=state.compare.filter(id=>!ids.has(id));save();closeModal();render();break}case'download-template':download('id,instituteId,instituteName,city,state,type,exam,course,counselling,quota,category,year,round,openingRank,closingRank,seats,annualFee,monthlyStipend,bondYears,bondPenalty,previousSeats,sourceUrl,sourceLabel\n','zyjock-import-template.csv','text/csv');break}});
document.addEventListener('change',async event=>{const t=event.target;if(t.id==='global-exam'){state.exam=t.value;state.filters={};save();render()}else if(t.id==='global-mode'){state.mode=t.value;state.filters={};save();render()}else if(t.dataset.select==='list'){state.activeList=t.value;save();render()}else if(t.dataset.check){state.checklist[t.dataset.check]=t.checked;save();render()}else if(t.id==='dataset-file'&&t.files[0]){await importDataset(t.files[0]);t.value=''}else if(t.id==='backup-file'&&t.files[0]){await restoreBackup(t.files[0]);t.value=''}});
document.querySelector('.skip-link').addEventListener('click',event=>{event.preventDefault();$('#main')?.focus();$('#main')?.scrollIntoView({block:'start'});});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,f=Object.fromEntries(new FormData(form));switch(form.id){case'specialty-search':state.branchSearch=f.search;render();break;case'profile-form':state.profile=f;save();toast('Your PG plan is saved on this device.');render();break;case'filter-form':if(f.includeZero==='yes'&&!data.zeroLoaded){try{await loadZeroRows()}catch(err){toast(err.message,'warning');break}}state.visible=36;state.sort=f.sort;delete f.sort;state.filters=f;render();break;case'quick-rank':state.filters={rank:f.rank,category:f.category||''};navigate('cutoffs');break;case'list-form':if(!f.name.trim()){toast('Enter a list name.','warning');break}if(f.rename==='yes')selectedList().name=f.name.trim();else{const l={id:ID(),name:f.name.trim(),items:[]};state.lists.push(l);state.activeList=l.id}save();closeModal();render();toast('Choice list saved.');break;case'builder-form':{const rows=generateChoices(baseRecords().filter(r=>r.seats!==0),{...f,sort:f.priority,limit:Number(f.limit),deduplicate:true},institutes());if(!rows.length){toast('No records match. Try broader preferences or another dataset.','warning');break}const l={id:ID(),name:`${state.exam} · ${f.state||'All states'} · ${new Date().toLocaleDateString('en-IN')}`,items:rows.slice(0,Number(f.limit)).map(r=>r.id)};state.lists.push(l);state.activeList=l.id;save();render();toast(`Created a draft with ${l.items.length} choices.`);break}case'reminder-form':if(!f.title.trim()){toast('Enter a reminder title.','warning');break}state.reminders.push({id:ID(),title:f.title.trim(),date:f.date});save();closeModal();render();toast('Reminder saved on this device.');break;case'cost-form':{const tuition=Number(f.tuition)*Number(f.years),living=Number(f.living)*12*Number(f.years),stipend=Number(f.stipend)*12*Number(f.years);$('#cost-result').innerHTML=`<div class="rank-result"><span class="metric-label">Estimated net study budget</span><strong class="rank-number">${money(tuition+living-stipend)}</strong><p>Tuition ${money(tuition)} + living ${money(living)} − stipend ${money(stipend)}.</p><p class="small">Based only on your inputs. Excludes deposits, additional fees, inflation and bond penalties.</p></div>`;break}case'guide-form':{const terms=f.question.toLowerCase().split(/\W+/).filter(w=>w.length>2);const hits=data.guides.map(g=>({g,score:terms.reduce((s,w)=>s+(g.title+' '+g.body).toLowerCase().includes(w),0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,3);$('#guide-results').innerHTML=hits.length?`<div class="section-gap">${hits.map(({g})=>`<article class="guide-card"><h3>${e(g.title)}</h3><p>${e(g.body)}</p>${external(g.sourceUrl,'Official source')}</article>`).join('')}</div>`:`<p class="data-note">No matching guide yet. Try “choice”, “documents”, “fees” or “eligibility”, or use an official resource below.</p>`;break}}});
document.addEventListener('keydown',event=>{const modal=$('#modal-root .modal');if(!modal)return;if(event.key==='Escape'){closeModal();return}if(event.key==='Tab'){const focusables=[...modal.querySelectorAll('a[href],button:not([disabled]),input,select,textarea,summary')];const first=focusables[0],last=focusables.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});
window.addEventListener('hashchange',event=>{const before=new URL(event.oldURL).hash.slice(1),after=route();if(['cutoffs','rounds'].includes(before)!==['cutoffs','rounds'].includes(after)){delete state.filters.year;delete state.filters.round}state.visible=36;state.mobileOpen=false;render()});

async function importDataset(file){try{if(file.size>5*1024*1024)throw new Error('Choose a file smaller than 5 MB.');const text=await file.text();let rows=file.name.toLowerCase().endsWith('.csv')?parseCSV(text):JSON.parse(text);if(!Array.isArray(rows))rows=rows.records;if(!Array.isArray(rows))throw new Error('Use a CSV or a JSON array of records.');const result=validateImport(rows);if(!result.valid){openModal('Some rows need attention',`<p>Your file has not been imported. Fix these items and try again.</p><ul>${result.errors.slice(0,15).map(er=>`<li>Row ${e(er.row)} · ${e(er.field)}: ${e(er.message)}</li>`).join('')}</ul>`);return}const importId=ID();const newInstitutes=[],newRecords=[];result.records.forEach((r,index)=>{const original=rows[index]||{},provided=original.instituteId;let target=provided&&institutes().find(i=>i.id===provided);if(!target){const name=String(original.instituteName||provided||'Imported institution');target=newInstitutes.find(i=>i.name===name&&i.state===(original.state||'Unknown'));if(!target){target={id:`import-${importId}-${newInstitutes.length}`,name,city:String(original.city||''),state:String(original.state||'Unknown'),type:String(original.type||'Imported'),verified:false};newInstitutes.push(target)}}newRecords.push({...r,recordKind:r.closingRank!==null?'cutoff':'seat-matrix',specialty:r.specialty||r.course,program:r.program||'Imported',id:`import-${importId}-${index}`,instituteId:target.id,dataStatus:'imported',sourceLabel:r.sourceLabel||'User supplied · unverified'})});state.imports.records.push(...newRecords);state.imports.institutes.push(...newInstitutes);state.mode='imported';state.exam=newRecords[0]?.exam||state.exam;state.filters={};save();render();toast(`Imported ${newRecords.length} unverified records.`)}catch(err){toast(`Import failed: ${err.message}`,'warning')}}
async function restoreBackup(file){try{if(file.size>5*1024*1024)throw new Error('Choose a backup smaller than 5 MB.');const b=JSON.parse(await file.text());if(b.format!=='zyjock-workspace'||b.version!==1||!Array.isArray(b.lists))throw new Error('This is not a supported Zyjock backup.');const imports=b.imports||{records:[],institutes:[]};if(!Array.isArray(imports.records)||!Array.isArray(imports.institutes))throw new Error('Malformed imported dataset.');if(imports.records.length){const validated=validateImport(imports.records);if(!validated.valid)throw new Error('The backup contains invalid records.');imports.records=validated.records.map((r,index)=>({...r,id:imports.records[index].id,dataStatus:'imported'}))}for(const i of imports.institutes){if(!i||typeof i.id!=='string'||typeof i.name!=='string')throw new Error('Invalid institution in backup.')}const knownInstitutes=new Set([...institutes().map(i=>i.id),...imports.institutes.map(i=>i.id)]);if(imports.records.some(r=>typeof r.id!=='string'||!r.id.startsWith('import-')||!knownInstitutes.has(r.instituteId)))throw new Error('Invalid imported record identity.');const allowed=new Set([...records().map(r=>r.id),...imports.records.map(r=>r.id)]);const lists=b.lists.map(l=>{if(!l||typeof l.name!=='string'||!Array.isArray(l.items)||l.items.some(id=>typeof id!=='string'))throw new Error('Invalid choice list in backup.');return{id:ID(),name:l.name.trim().slice(0,80)||'Restored list',items:unique(l.items.filter(id=>allowed.has(id)))}});const reminders=(b.reminders||[]).map(r=>{if(!r||typeof r.title!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(r.date))throw new Error('Invalid reminder in backup.');return{id:ID(),title:r.title.slice(0,120),date:r.date}});const existingRecords=new Set(state.imports.records.map(r=>r.id)),existingInstitutes=new Set(institutes().map(i=>i.id));state.imports.records.push(...imports.records.filter(r=>!existingRecords.has(r.id)).map(r=>({...r,dataStatus:'imported'})));state.imports.institutes.push(...imports.institutes.filter(i=>!existingInstitutes.has(i.id)));state.lists.push(...lists);state.reminders.push(...reminders);if(b.profile&&typeof b.profile==='object')state.profile=Object.fromEntries(['rank','category','specialty','state','maxFee'].map(k=>[k,String(b.profile[k]||'').slice(0,160)]));for(const [key]of checks)if(b.checklist?.[key]===true)state.checklist[key]=true;save();render();toast(`Restored ${lists.length} lists and ${reminders.length} reminders.`)}catch(err){toast(`Restore failed: ${err.message}`,'warning')}}

function hydrateRows(rows){return rows.map(r=>({...data.recordDefaults,...r,...(r.sourceId?{sourceUrl:data.sourceIndex[r.sourceId].url,sourceLabel:data.sourceIndex[r.sourceId].title}:{}),...(r.historicalSourceId?{historicalSourceUrl:data.sourceIndex[r.historicalSourceId].url}:{}),...(r.financialSourceId?{financialSourceUrl:data.sourceIndex[r.financialSourceId].url}:{})}))}
async function loadZeroRows(){if(data.zeroLoaded)return;toast('Loading the explicitly published zero-seat pools…');const chunks=await Promise.all((data.zeroRecordFiles||[]).map(async file=>{const r=await fetch(file);if(!r.ok)throw new Error('Zero-seat dataset could not be loaded.');return r.json()}));data.records.push(...hydrateRows(chunks.flat()));data.zeroLoaded=true;refreshCatalog()}
async function boot(){try{const response=await fetch('./data.json');if(!response.ok)throw new Error('Dataset could not be loaded.');data=await response.json();if(!Array.isArray(data.records)||!Array.isArray(data.institutes))throw new Error('Dataset is malformed.');if(Array.isArray(data.recordFiles)){const chunks=await Promise.all(data.recordFiles.map(async file=>{const r=await fetch(file);if(!r.ok)throw new Error('A PG dataset could not be loaded.');return r.json()}));data.records=hydrateRows(chunks.flat());}data.resources??=[];data.notices??=[];data.guides??=[];refreshCatalog();if(!EXAMS.includes(state.exam))state.exam='NEET PG';if(!['verified','imported','all'].includes(state.mode))state.mode='verified';render()}catch(err){$('#app').innerHTML=`<main class="empty-state" style="padding:4rem"><h1>Let’s get your workspace back.</h1><p>${e(err.message)}</p><button onclick="location.reload()">Try again</button></main>`}}
boot();
